from fastapi import FastAPI, HTTPException, status
from httpx import ASGITransport, AsyncClient
from pydantic import BaseModel

app = FastAPI()
EMAILS = {"karim@exemple.fr"}


class Inscription(BaseModel):
    email: str


@app.post("/inscriptions", status_code=status.HTTP_201_CREATED)
async def inscrire(inscription: Inscription):
    if inscription.email in EMAILS:
        raise HTTPException(status.HTTP_409_CONFLICT, detail="Cet email est déjà inscrit")
    EMAILS.add(inscription.email)
    return {"email": inscription.email}


async with AsyncClient(transport=ASGITransport(app=app), base_url="http://test") as client:
    for email in ("camille@exemple.fr", "camille@exemple.fr"):
        reponse = await client.post("/inscriptions", json={"email": email})
        print(reponse.status_code, reponse.json())

