from datetime import date

from fastapi import FastAPI
from httpx import ASGITransport, AsyncClient
from pydantic import BaseModel, field_validator, model_validator

app = FastAPI()


class Conges(BaseModel):
    salarie: str
    debut: date
    fin: date

    @field_validator("salarie")
    @classmethod
    def nettoyer(cls, valeur: str) -> str:
        return valeur.strip().title()

    @model_validator(mode="after")
    def dates_coherentes(self):
        if self.fin < self.debut:
            raise ValueError("La fin doit suivre le début")
        return self


@app.post("/conges")
async def demander(conges: Conges):
    return {"salarie": conges.salarie, "jours": (conges.fin - conges.debut).days + 1}


async with AsyncClient(transport=ASGITransport(app=app), base_url="http://test") as client:
    print((await client.post("/conges", json={"salarie": " camille martin ", "debut": "2026-08-03", "fin": "2026-08-14"})).json())
    erreur = (await client.post("/conges", json={"salarie": "Karim", "debut": "2026-08-14", "fin": "2026-08-03"})).json()
    print(erreur["detail"][0]["msg"])

blocs.markdown:
Pour finir, une API de gestion de tâches, organisée selon les conventions **REST** : une ressource (`/taches`) et des méthodes HTTP qui disent quoi faire.

- `POST /taches` : créer une tâche, réponse 201 ;
- `GET /taches` : lister, avec un filtre facultatif ;
- `GET /taches/{id}` : lire une tâche, ou 404 ;
- `PATCH /taches/{id}` : modifier **une partie** d'une tâche ;
- `DELETE /taches/{id}` : supprimer, réponse 204.

Les tâches sont gardées en mémoire dans un dictionnaire : le parcours intermédiaire branche une vraie base de données.

